// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {NewIntelTechMedia} from "../src/NewIntelTechMedia.sol";

contract InvMutTest is Test {
    NewIntelTechMedia c;
    function setUp() public { c = new NewIntelTechMedia(); }
    function testFuzz_property(address to, uint256 amount) public {
        vm.assume(to != address(0));
        amount = bound(amount, 1, 250000000e18);

        vm.prank(address(this));
        c.NETM();

        address owner = address(this);
        require(c.balanceOf(owner) > 0, "setup: owner balance must be > 0");

        bool success;
        vm.prank(owner);
        try c.transfer(to, amount) {
            success = true;
        } catch {
            success = false;
        }

        assertTrue(success);
    }
}
